using System;
using UnityEngine;

namespace GC26.Core
{
    /// <summary>Mirror of Assets/Microgames/&lt;id&gt;/microgame.json.</summary>
    [Serializable]
    public class MicrogameManifest
    {
        public string id;
        public string title;
        public string description;
        public string entry_scene;
        public string[] authors;
    }

    /// <summary>Generated by GC26 → Sync Microgames into Resources/gc26_registry.json.</summary>
    [Serializable]
    public class MicrogameRegistry
    {
        public const string ResourcePath = "gc26_registry";

        public MicrogameManifest[] games = Array.Empty<MicrogameManifest>();

        public static MicrogameRegistry Load()
        {
            var asset = Resources.Load<TextAsset>(ResourcePath);
            return asset ? JsonUtility.FromJson<MicrogameRegistry>(asset.text) : new MicrogameRegistry();
        }
    }
}
